// ─── Produk Komersial — Batch 1 — Produk (SKU) Registry ──────────────────────
// PK-R02A: Produk/SKU individual milik satu Seri. Ini adalah level paling
// bawah dari hierarki Kategori → Brand → Seri → Produk. Setiap produk WAJIB
// memiliki UUID, nama, brand, seri, kategori, kemasan, deskripsi singkat, dan
// status aktif — sesuai kontrak PK-R02A.
//
// Data ini juga diproyeksikan ke PRODUK_KOMERSIAL_LIST generik
// (produkKomersialData.ts) agar otomatis terhitung pada Ringkasan/Dashboard
// dan otomatis tersedia untuk dipilih Formula lewat readiness layer PK-005
// (formulaProdukKomersialData.ts) — tanpa mengubah struktur Formula itu sendiri.

export interface ProdukKomersialBatch1Item {
  uuid: string;
  seriId: string; // UUID → ProdukKomersialSeri.uuid
  brandId: string; // UUID → ProdukKomersialBrand.uuid
  kategoriId: string; // UUID → KATEGORI_UUID
  kategoriSlug: string; // routing only
  slug: string;
  namaProduk: string;
  kemasan: string;
  deskripsi: string;
  statusAktif: boolean;
  updatedAt: string;
  // Optional rich fields — PK-R03A.3B
  hargaReferensi?: number;
  hargaPerKg?: number;
}

