/** Daftar produk milik satu seri (UUID). */
export function getProdukBySeriId(seriId: string): ProdukKomersialBatch1Item[] {
  return PK_BATCH1_PRODUK_LIST.filter(p => p.seriId === seriId);
}

/** Lookup satu produk via seriId + produkSlug (routing). */
export function getProdukBySlug(seriId: string, produkSlug: string): ProdukKomersialBatch1Item | undefined {
  return PK_BATCH1_PRODUK_LIST.find(p => p.seriId === seriId && p.slug === produkSlug);
}

/** Lookup produk via UUID. */
export function getProdukByUUID(uuid: string): ProdukKomersialBatch1Item | undefined {
  return PK_BATCH1_PRODUK_LIST.find(p => p.uuid === uuid);
}

/** Jumlah produk pada satu kategori (slug), dihitung live. */
export function getJumlahProdukByKategoriSlug(kategoriSlug: string): number {
  return PK_BATCH1_PRODUK_LIST.filter(p => p.kategoriSlug === kategoriSlug).length;
}
